var t=`1263-bahamian-fish-stew`;var a=`world-1263`;var n=`BS`;var s=`central-america-caribbean`;var o=4;var r=55;var m={en:`Bahamian Fish Stew`,ua:`Багамське рибне рагу`};var l={en:`Bahamian Fish Stew is a dish from Bahamas featuring yellow onion, celery stalk, green bell pepper, tomato. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Багамське рибне рагу, страва кухні країни Багамські Острови з такими основними складниками: жовта цибуля, стебло селери, зелений солодкий перець, помідор. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var g=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,170,`g`],[`celery-stalk`,130,`g`],[`green-bell-pepper`,160,`g`],[`canola-oil`,35,`ml`]]},{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 25 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 25 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:25,i:[[`tomato`,380,`g`],[`fish-stock`,850,`ml`],[`thyme`,4,`sprig`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 17 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 17 хвилин до готовності й м’якості.`,t:[`poaching`],m:17,i:[[`red-snapper`,780,`g`],[`potato`,310,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lime-juice`,60,`ml`],[`parsley`,20,`g`]]}];var h={slug:t,id:a,country:`BS`,region:s,servings:4,minutes:55,title:m,text:l,steps:g};export{n as country,h as default,a as id,r as minutes,s as region,o as servings,t as slug,g as steps,l as text,m as title};